//   JoeLovano.grammar  — post-bop, 37% minor density (Phase 3.5)
//   JimmyHeath.grammar — hard-bop, 35% minor (Phase 3.5)
//   RichPerry.grammar  — modal jazz, 31% minor + Descending-Minor-CESH
// Each lick is one rule, converted from Impro-Visor's (X DEGREE DURATION)
// chord-relative notation. Each note carries BOTH the eagerly-parsed
// chromaticOffset (semitones above root, fixed) AND the original
// degreeLabel string. The engine prefers degreeLabel at play time and
// resolves it through resolveDegree(label, chordType) — Impro-Visor's
// chord-family-aware mechanism — so the SAME lick fits major / minor /
// dom7 / m7b5 chords with the correct 3rd / 7th automatically
// (e.g. "(X 3 8)" plays 4 semis on maj7, 3 semis on m7).
//
// brickType field = harmonic context the lick was authored for:
//   Sad-Cadence / Straight-Cadence / Surprise-Major-Cadence — V→I family
//   Dropback                                                — turnaround
//   Tension-Cadence / Starlight-Cadence / Yardbird-Cadence   — colored V
//   Long-Cadence / Two-Goes-Straight-Cadence                — extended ii-V-I
//
// Engine consumer: motif pool injection (MACRO_MOTIF_POOLS.LOFI)
//   - cadence bricks → ends pool (phrase-end cell)
//   - Dropback / turnaround → starts pool (phrase-start cell)
//   - Long-Cadence etc. → flows pool (middle cells)
// ==========================================

export interface ImprovisorLick {
  id: string;
  source: string;  // 'BillEvans' | 'JoeLovano' | 'JimmyHeath' | 'RichPerry'
  /**
   * 'original' = parsed directly from the source grammar.
   * 'thinned'  = derived by dropping ~50% of weak-position notes from
   *              a denser source (Phase 2 transform). Same total length,
   *              fewer notes — converts BillEvans's Q-fragment density
   *              into LOFI-shape sparsity.
   * 'augmented'= derived by stretching a short (≤6 note) lick ×2 or
   *              ×1.5 in time. Same pitch contour, half-time feel.
   */
  variant: 'original' | 'thinned' | 'augmented';
  brickType: string;
  bars: number;
  notes: Array<{
    t: number;
    d: number;
    chromaticOffset: number;
    /** Original Impro-Visor degree label ("3", "b3", "b9", "#11", ...).
     *  Engine prefers this over chromaticOffset when present and
     *  resolves via resolveDegree(label, chord.type) so chord family
     *  picks the right 3rd / 7th. */
    degreeLabel?: string;
  }>;
}

