// 按 brick type 分组的索引 — engine 按 cell role 选 lick 时用
export const LICKS_BY_BRICK: Record<string, ImprovisorLick[]> = (() => {
  const out: Record<string, ImprovisorLick[]> = {};
  for (const l of IMPROVISOR_LICKS) {
    (out[l.brickType] ??= []).push(l);
  }
  return out;
})();

// Cell role → 可选 brick 类型映射.
//   establish: Q-fragment (开头铺陈,无终止感) + Dropback (turnaround 启动)
//   develop:   Q-fragment (中段) + Long-Cadence
//   lift:      Long-Cadence + 全部 cadence (即将抵达,带能量)
//   cadence:   全部 cadence (终止式)
export const LICKS_BY_CELL_ROLE: Record<'establish' | 'develop' | 'lift' | 'cadence', ImprovisorLick[]> = (() => {
  const cadenceBricks = ['Sad-Cadence', 'Straight-Cadence', 'Surprise-Major-Cadence', 'Tension-Cadence', 'Starlight-Cadence', 'Yardbird-Cadence', 'Major-Cadence', 'Minor-Cadence'];
  const turnaroundBricks = ['Dropback'];
  const longBricks = ['Long-Cadence', 'Two-Goes-Straight-Cadence'];
  const qFragments = ['Q-fragment'];
  return {
    establish: IMPROVISOR_LICKS.filter(l => turnaroundBricks.includes(l.brickType) || qFragments.includes(l.brickType)),
    develop:   IMPROVISOR_LICKS.filter(l => longBricks.includes(l.brickType) || turnaroundBricks.includes(l.brickType) || qFragments.includes(l.brickType)),
    lift:      IMPROVISOR_LICKS.filter(l => longBricks.includes(l.brickType) || cadenceBricks.includes(l.brickType)),
    cadence:   IMPROVISOR_LICKS.filter(l => cadenceBricks.includes(l.brickType)),
  };
})();
